  1	export const dynamic = "force-dynamic";
  2	
  3	import { requireUser } from "@/lib/auth";
  4	import { db } from "@/lib/db";
  5	import { gameSubdomainBase } from "@/lib/game-subdomain-dns";
  6	import { GAME_DISPLAY, GAME_ART_SLUG, type GameFamily } from "@/lib/games";
  7	import { REGION_LABELS, REGION_COUNTRY } from "@/lib/node-regions";
  8	import { queryAll, canQuery } from "@/lib/server-query";
  9	import { ToolsAurora } from "@/components/nx/ToolsAurora";
 10	import { DirectoryView, type DirectoryRow } from "@/components/nx/DirectoryView";
 11	
 12	/**
 13	 * The server directory, inside the portal.
 14	 *
 15	 * There WAS a directory — at /game-servers/directory, on the marketing site —
 16	 * and the portal's only relationship to it was a link out to a public page. So
 17	 * a customer browsing servers left the product to do it, came back through the
 18	 * marketing site, and the page they landed on knew nothing about them. This is
 19	 * the same data as a real page in the app, with the things a portal can add
 20	 * that a marketing page can't: the region a server actually runs in, and a live
 21	 * player count queried from the server itself.
 22	 *
 23	 * PRIVACY. These are OTHER customers' servers. A row carries what its owner
 24	 * chose to publish — the name, their description, the connect address — and
 25	 * nothing else. No owner, no internal id, and specifically no raw node IP: a
 26	 * server with no play subdomain is not listed at all, exactly as the marketing
 27	 * directory already decided. The live probe runs server-side against the public
 28	 * address, the same request any player's game client makes.
 29	 *
 30	 * LIVE COUNTS come from lib/server-query.ts, which speaks the three protocols a
 31	 * stranger is allowed to ask: Minecraft's Server List Ping, Bedrock's RakNet
 32	 * ping, and Valve's A2S_INFO. That covers twenty-eight of the catalogue's
 33	 * families; the rest list their slot count and no live figure, because there is
 34	 * no honest way to produce one. A probe that times out is treated the same as
 35	 * one that can't be made — no number, never a zero.
 36	 */
 37	
 38	export default async function DirectoryPage() {
 39	  await requireUser();
 40	  const base = await gameSubdomainBase();
 41	
 42	  const [paid, free] = await Promise.all([
 43	    db.server.findMany({
 44	      where: { publicListing: true, status: "RUNNING", gamePlan: { isNot: null } },
 45	      select: {
 46	        id: true, name: true, label: true, publicDescription: true, subdomain: true,
 47	        gamePlan: { select: { slots: true, gameFamily: true } },
 48	        osTemplate: { select: { family: true } },
 49	        node: { select: { region: true } },
 50	        gameVariant: true,
 51	      },
 52	      orderBy: { createdAt: "asc" },
 53	    }),
 54	    db.freeMinecraftServer.findMany({
 55	      where: { isPublic: true, status: "READY" },
 56	      select: {
 57	        id: true, name: true, subdomain: true,
 58	        publicTagline: true, publicDescription: true,
 59	        activeGameType: true, activeGameMode: true,
 60	      },
 61	      orderBy: { createdAt: "asc" },
 62	    }),
 63	  ]);
 64	
 65	  const rows: DirectoryRow[] = [];
 66	
 67	  for (const s of paid) {
 68	    // No play subdomain, no listing — a raw node IP is not ours to publish.
 69	    if (!s.subdomain) continue;
 70	    const family = (s.gamePlan?.gameFamily ?? s.osTemplate?.family ?? "minecraft") as GameFamily;
 71	    rows.push({
 72	      key: `p-${s.id.slice(0, 10)}`,
 73	      name: s.label || s.name,
 74	      description: s.publicDescription,
 75	      address: `${s.subdomain}.${base}`,
 76	      family,
 77	      gameLabel: GAME_DISPLAY[family]?.name ?? family,
 78	      art: GAME_ART_SLUG[family]?.hero ?? null,
 79	      variant: s.gameVariant,
 80	      slots: s.gamePlan?.slots ?? null,
 81	      region: s.node?.region ?? null,
 82	      regionLabel: s.node?.region ? REGION_LABELS[s.node.region] ?? s.node.region : null,
 83	      regionCountry: s.node?.region ? REGION_COUNTRY[s.node.region] ?? null : null,
 84	      isFree: false,
 85	      queryable: canQuery(family),
 86	      online: null,
 87	      onlineMax: null,
 88	      motd: null,
 89	      map: null,
 90	    });
 91	  }
 92	
 93	  for (const s of free) {
 94	    rows.push({
 95	      key: `f-${s.id.slice(0, 10)}`,
 96	      name: s.name || s.subdomain,
 97	      description: s.publicDescription || s.publicTagline,
 98	      address: `${s.subdomain}.${base}`,
 99	      family: "minecraft",
100	      gameLabel: GAME_DISPLAY.minecraft?.name ?? "Minecraft",
101	      art: GAME_ART_SLUG.minecraft?.hero ?? null,
102	      variant: s.activeGameType !== "vanilla" ? s.activeGameType : null,
103	      slots: null,
104	      /* Every free server is a container on the shared free-tier node, so there
105	         is no per-server node row to read a region from. Named for what it is
106	         rather than left blank or, worse, guessed. */
107	      region: "freemc",
108	      regionLabel: "Free tier node",
109	      regionCountry: null,
110	      isFree: true,
111	      queryable: true,
112	      online: null,
113	      onlineMax: null,
114	      motd: null,
115	      map: null,
116	    });
117	  }
118	
119	  /* One probe per listed server, bounded. Every one of these is a request the
120	     public internet could make anyway — it is the same packet a player's game
121	     client sends when it draws its own server list. */
122	  const live = await queryAll(rows.map((r) => ({ family: r.family, address: r.address })));
123	  for (const r of rows) {
124	    const l = live.get(r.address);
125	    if (!l) continue;
126	    r.online = l.online;
127	    r.onlineMax = l.max ?? r.slots;
128	    r.motd = l.motd;
129	    r.map = l.map;
130	  }
131	
132	  /* Servers that answered, busiest first, then the rest. A directory is for
133	     finding somewhere with people in it. */
134	  rows.sort((a, b) => {
135	    const ao = a.online ?? -1;
136	    const bo = b.online ?? -1;
137	    if (ao !== bo) return bo - ao;
138	    return a.name.localeCompare(b.name);
139	  });
140	
141	  return (
142	    <>
143	      <ToolsAurora />
144	      <div className="relative z-[1] mx-auto flex w-full max-w-[1520px] flex-col gap-5">
145	        <DirectoryView rows={rows} />
146	      </div>
147	    </>
148	  );
149	}

