 10	/**
 11	 * Browse every server other customers have chosen to publish.
 12	 *
 13	 * Each card leads with the game's own key art, because that is what people
 14	 * actually scan for. Everything under it is real: the connect address its owner
 15	 * published, the region the machine is genuinely in, and — where the game
 16	 * answers a public query at all — how many people are on it right now, read
 17	 * from the server a moment ago rather than from anything we store.
 18	 *
 19	 * A card with no live figure is showing the truth for its game. Twenty-eight of
 20	 * the catalogue's families answer a public query; the rest have no such
 21	 * protocol (see lib/server-query.ts), so those cards say what the game reports
 22	 * instead of drawing a zero that would read as "empty server".
 23	 */
 24	
 25	export type DirectoryRow = {
 26	  key: string;
 27	  name: string;
 28	  description: string | null;
 29	  address: string;
 30	  family: string;
 31	  gameLabel: string;
 32	  art: string | null;
 33	  variant: string | null;
 34	  slots: number | null;
 35	  region: string | null;
 36	  regionLabel: string | null;
 37	  regionCountry: string | null;
 38	  isFree: boolean;
 39	  /** Whether this game answers a public query at all. */
 40	  queryable: boolean;
 41	  online: number | null;
 42	  onlineMax: number | null;
