282	            server and turn on its public listing.
283	          </p>
284	          <Link href="/dashboard/services" className="nx-cta mt-5 inline-block px-5 py-2.5 text-[13px]">
285	            My services
286	          </Link>
287	        </div>
288	      ) : shown.length === 0 ? (
289	        <p className="rounded-[14px] border border-rim-hi bg-well px-5 py-12 text-center text-[12.5px] text-tx-faint">
290	          No servers match that.
291	        </p>
292	      ) : (
293	        <>
294	          <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4">
295	            {shown.slice(0, limit).map((r) => <Card key={r.key} row={r} />)}
296	          </div>
297	          {shown.length > limit && (
298	            <button
299	              type="button"
300	              onClick={() => setLimit((n) => n + PAGE)}
301	              className="mx-auto rounded-[11px] border border-rim-hi bg-well px-5 py-2.5 text-[12.5px] font-semibold text-tx-dim transition hover:border-brand-400/45 hover:text-white"
302	            >
303	              Show more — {shown.length - limit} left
304	            </button>
305	          )}
306	        </>
307	      )}
308	
309	      <p className="text-[11.5px] leading-relaxed text-tx-faint">
310	        Counts are read live from each server using the same public query its own game client uses.
311	        Some games have no such protocol at all — those servers show their slot count instead of a
312	        number nobody could honestly produce.
313	      </p>
314	    </>
315	  );
316	}

