  3	import { joinPortFor, type GameFamily } from "./games";
  4	
  5	/**
  6	 * Asking a game server, over the public internet, who is on it.
  7	 *
  8	 * WHY THIS EXISTS. The directory needs a live player count, and the only source
  9	 * we had was `PlayerSession`, written by worker/game-control.ts's RCON sweep —
 10	 * which covers three families out of forty-six, because everything else has
 11	 * `rcon: "none"`. A directory that says "0 players" for forty-three games isn't
 12	 * a directory. These are the protocols a server answers to ANYONE, with no
 13	 * credentials, which is exactly what a public listing needs.
 14	 *
 15	 * WHICH GAMES CAN BE LISTED — the question this module answers concretely:
 16	 *
 17	 *   mc-java   Minecraft Java's Server List Ping. A TCP handshake plus a status
 18	 *             request; the reply is the same JSON a vanilla client shows in its
 19	 *             server list. Unauthenticated by design.
 20	 *   bedrock   Minecraft Bedrock's RakNet "unconnected ping". One UDP datagram,
 21	 *             and the reply is a semicolon-delimited MOTD string carrying the
 22	 *             player counts.
 23	 *   a2s       Valve's A2S_INFO. One UDP datagram to the game's query port. Since
 24	 *             2020 the server usually replies with a challenge first and the
 25	 *             query has to be re-sent with it — handled below. Every Source
 26	 *             engine title speaks it, and so does every Steam-networking
 27	 *             dedicated server, which is most of the survival catalogue.
