/** Toggle whether this server appears in the public server directory. */
export async function togglePublicListing(serverId: string, enabled: boolean): Promise<Result> {
  try {
    await ownedServer(serverId);
    await db.server.update({ where: { id: serverId }, data: { publicListing: enabled } });
    revalidatePath("/game-servers/directory");
    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true };
  } catch (err) { return { ok: false, error: safeError(err) }; }
}

/** Update the public description shown in the server directory. Max 500 chars. */
export async function updatePublicDescription(serverId: string, description: string): Promise<Result> {
  try {
    await ownedServer(serverId);
    const trimmed = description.trim().slice(0, 500);
    await db.server.update({ where: { id: serverId }, data: { publicDescription: trimmed || null } });
    revalidatePath("/game-servers/directory");
    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true };
  } catch (err) { return { ok: false, error: safeError(err) }; }
}

/** Read the current public listing state for the owner's panel. */
export async function getPublicListingState(serverId: string): Promise<
  { ok: true; publicListing: boolean; publicDescription: string | null } | { ok: false; error: string }
> {
  try {
    await ownedServer(serverId);
    const row = await db.server.findUnique({
      where: { id: serverId },
      select: { publicListing: true, publicDescription: true },
    });
    if (!row) return { ok: false, error: "Server not found." };
    return { ok: true, publicListing: row.publicListing, publicDescription: row.publicDescription };
  } catch (err) { return { ok: false, error: safeError(err) }; }
}

"use server";

/**
 * Opt-in public listing controls for a free Minecraft server — purely a DB
 * update gating what's shown on the public directory (/servers) and the
 * server's own shareable page (/servers/[subdomain]). Never touches the
 * container, SSH, or mc-router: making a server "public" only changes whether
 * its address/description is exposed on those pages, not how it's reached —
 * the server was already joinable at its subdomain the moment it existed.
 *
 * Sibling to lib/actions-free-minecraft.ts, kept in its own file so the
 * directory feature can be reviewed/shipped independently of the core
 * create/power/settings actions.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";

type Result = { error?: string; ok?: boolean };

const TAGLINE_MAX = 80;
const DESCRIPTION_MAX = 600;

export async function updateFreeMinecraftPublicListing(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const rl = checkRateLimit(`freemc:public-listing:${user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  const isPublic = formData.get("isPublic") === "on" || formData.get("isPublic") === "true";
  // Rendered as plain text (never dangerouslySetInnerHTML) on the public pages,
  // so no HTML sanitization is needed here — just trim whitespace and cap
  // length so a listing can't blow out the directory/card layout.
  const publicTagline = String(formData.get("publicTagline") ?? "").trim().slice(0, TAGLINE_MAX);
  const publicDescription = String(formData.get("publicDescription") ?? "").trim().slice(0, DESCRIPTION_MAX);

  await db.freeMinecraftServer.update({
    where: { id: row.id },
    data: {
      isPublic,
      publicTagline: publicTagline || null,
      publicDescription: publicDescription || null,
    },
  });

  revalidatePath("/dashboard/free-minecraft");
  revalidatePath("/servers");
  revalidatePath(`/servers/${row.subdomain}`);
  return { ok: true };
}
